import test from 'node:test';
import assert from 'node:assert';
import { roundCents, formatEuros, parseEuros, RATES, convert, formatMoney } from '../src/money.js';

test('roundCents rounds half to even', () => {
  assert.strictEqual(roundCents(124.5), 124);
  assert.strictEqual(roundCents(125.5), 126);
  assert.strictEqual(roundCents(2.4), 2);
  assert.strictEqual(roundCents(-0.5), 0);
});

test('roundCents ignores binary noise', () => {
  assert.strictEqual(roundCents(124.49999999999999), 124);
});

test('formatEuros adds the sign, thousands separators and two decimals', () => {
  assert.strictEqual(formatEuros(123456), '€1,234.56');
  assert.strictEqual(formatEuros(-5), '-€0.05');
});

test('parseEuros reads what people type', () => {
  assert.deepStrictEqual(parseEuros('12'), { ok: true, value: 1200 });
  assert.deepStrictEqual(parseEuros('12.5'), { ok: true, value: 1250 });
  assert.deepStrictEqual(parseEuros('1,234.56'), { ok: true, value: 123456 });
});

test('RATES includes EUR, USD, GBP', () => {
  assert.strictEqual(RATES.EUR, 1);
  assert.strictEqual(RATES.USD, 1.085);
  assert.strictEqual(RATES.GBP, 0.8425);
});

test('convert EUR to USD', () => {
  const result = convert(10000, 'USD');
  assert.strictEqual(result.ok, true);
  assert.strictEqual(result.value, 10850);
});

test('convert EUR to GBP', () => {
  const result = convert(10000, 'GBP');
  assert.strictEqual(result.ok, true);
  assert.strictEqual(result.value, 8425);
});

test('convert EUR to EUR (identity)', () => {
  const result = convert(10000, 'EUR');
  assert.strictEqual(result.ok, true);
  assert.strictEqual(result.value, 10000);
});

test('convert returns error for unknown currency', () => {
  const result = convert(10000, 'JPY');
  assert.strictEqual(result.ok, false);
  assert.strictEqual(result.error, 'UNKNOWN_CURRENCY');
});

test('convert handles rounding', () => {
  const result = convert(100, 'USD');
  // 100 * 1.085 = 108.5, rounds to 108 or 109 depending on banker's rounding
  assert.strictEqual(result.ok, true);
  assert(result.value === 108 || result.value === 109);
});

test('convert handles negative amounts', () => {
  const result = convert(-10000, 'USD');
  assert.strictEqual(result.ok, true);
  assert.strictEqual(result.value, -10850);
});

test('convert handles zero', () => {
  const result = convert(0, 'USD');
  assert.strictEqual(result.ok, true);
  assert.strictEqual(result.value, 0);
});

test('formatMoney formats USD', () => {
  assert.strictEqual(formatMoney(123456, 'USD'), '$1,234.56');
});

test('formatMoney formats GBP', () => {
  assert.strictEqual(formatMoney(123456, 'GBP'), '£1,234.56');
});

test('formatMoney formats EUR', () => {
  assert.strictEqual(formatMoney(123456, 'EUR'), '€1,234.56');
});

test('formatMoney handles negative USD', () => {
  assert.strictEqual(formatMoney(-5, 'USD'), '-$0.05');
});

test('formatMoney handles negative GBP', () => {
  assert.strictEqual(formatMoney(-5, 'GBP'), '-£0.05');
});

test('formatMoney handles negative EUR', () => {
  assert.strictEqual(formatMoney(-5, 'EUR'), '-€0.05');
});

test('formatMoney handles small amounts', () => {
  assert.strictEqual(formatMoney(1, 'USD'), '$0.01');
  assert.strictEqual(formatMoney(1, 'GBP'), '£0.01');
  assert.strictEqual(formatMoney(1, 'EUR'), '€0.01');
});

test('formatMoney handles large amounts', () => {
  assert.strictEqual(formatMoney(123456789, 'USD'), '$1,234,567.89');
  assert.strictEqual(formatMoney(123456789, 'GBP'), '£1,234,567.89');
});

test('formatMoney handles zero', () => {
  assert.strictEqual(formatMoney(0, 'USD'), '$0.00');
  assert.strictEqual(formatMoney(0, 'GBP'), '£0.00');
  assert.strictEqual(formatMoney(0, 'EUR'), '€0.00');
});

test('formatMoney returns unknown currency message for invalid currency', () => {
  assert.strictEqual(formatMoney(100, 'JPY'), 'Unknown currency');
});

test('convert with large amounts', () => {
  const result = convert(1000000, 'USD');
  assert.strictEqual(result.ok, true);
  assert.strictEqual(result.value, 1085000);
});

test('convert and formatMoney work together for USD', () => {
  const euroCents = 10000; // 100 EUR
  const converted = convert(euroCents, 'USD');
  assert.strictEqual(converted.ok, true);
  const formatted = formatMoney(converted.value, 'USD');
  assert.strictEqual(formatted, '$108.50');
});

test('convert and formatMoney work together for GBP', () => {
  const euroCents = 10000; // 100 EUR
  const converted = convert(euroCents, 'GBP');
  assert.strictEqual(converted.ok, true);
  const formatted = formatMoney(converted.value, 'GBP');
  assert.strictEqual(formatted, '£84.25');
});

